import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"周易口诀义 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"周易口诀义 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"zh/classics/koujueyi/035.md","filePath":"zh/classics/koujueyi/035.md"}'),r={name:"zh/classics/koujueyi/035.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><p>彖曰：「遁亨」，遁而亨也。刚当位而应，与时行也。「小利贞」，浸而长也。遁之时义大矣哉！</p><p>象曰：天下有山，遁。君子以远小人，不恶而严。</p><p>初六：遁尾，厉。勿用有攸往。</p><p>象曰：「遁尾」之厉，不往何灾也。</p><p>六二：执之用黄牛之革，莫之胜说。</p><p>象曰：执用黄牛，固志也。</p><p>九三：系遁，有疾，厉。畜臣妾，吉。</p><p>象曰：「系遁」之厉，有疾惫也。「畜臣妾吉」，不可大事也。</p><p>九四，好遁，君子吉，小人否。</p><p>象曰：君子「好遁」，「小人否」也。</p><p>九五，嘉遁，贞吉。</p><p>象曰：「嘉遁贞吉」，以正志也。</p><p>上九，肥遁，无不利。</p><p>象曰：「肥遁无不利」，无所疑也。</p><p>解读</p><p>「遁亨」者，遁是逃隐退避之名，谕小人道长，君子当退避而后可亨也。「小利贞」者，虽居小人道长之时，正道亦未全灭，亦可小利为正也。象曰「天下有山，遁」者，积阳为天，积阴为地，山者，阴长之象，山势渐长以逼于天，天性高远，逼而不至，如天渐高避于山。君子之远小人不恶而严者，处小人道长之世，近之必致危害，故须远避，不可与之为恶，又须庄敬严恭，自保其身也。</p><p>「初六，遁尾，厉，勿用有攸往」者，「尾」之为物，最在体后，处遁之时，众皆逃遁，唯初六最在于后，即必被执获，故致危厉。若能知尾为危，不如不往，即无灾害，故曰「勿用有攸往」也。</p><p>「六二，执之用黄牛之革，莫之胜说」者，黄，中色也，以譬中和也；牛革，即是牛皮，喻其厚顺也。处逃遁之时，众皆逃遁，唯六二得位守中，不肯逃遁，意欲率众以安其处。何以劝勉之？必须用中和之道，厚顺之德。有此之善，人莫胜己，可脱免逃遁而去也。</p><p>「九三，系遁，有疾厉，畜臣妾吉」者，夫亲昵小人，即为小人侵伤，故有疾惫危厉也。然亲洽于二，虽得如似畜养臣妾，不可兴建大事，故小象云「不可大事也」。</p><p>「九四，好遁，君子吉，小人否」者，有应在内，即情有所恋；身处于外，即志欲远遁。若知几君子，思虑危害，而能超然不顾所应，而好遁避，即获吉矣，故曰「好遁，君子吉」；小人处此，情有所恋，不肯遁，故曰「小人否」，「否」是否臧之「否」也。</p><p>「九五，嘉遁，贞吉」者，嘉，美也；五居尊位，为遁之主，率正小人之志，以安于俗，不令遁散，故获美善之吉也。</p><p>上九，肥遁，无不利者。肥者，优饶之名。上九处遁之时，最居于外，内又无应，即无顾恋，超然高举，不为小人所累，是逃遁之时而得优饶者也。既有如斯之德，即「无不利」矣。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
